sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {

    // More entities are loaded for a parent entity based on user action.

    var output = event.payload.data.output;
    setChildren(api.state.treeItems, api.state.currentPath, 0, output);

    function setChildren(items, path, index, output) {
        for (var i in items) {
            if (items[i].id == path[index]) {
                if (path.length - 1 == index) {
                    items[i].remainingChildren = output.result.remainingChildren;
                    items[i].childrenIds.push(...(output.result.downstreamIds));
                    var arr = items[i].children;
                    if (output.result.remainingChildren > 0) {
                        if ((arr.length>0) && arr[arr.length - 1].id == "show_more") {
                            items[i].children.pop(); 
                        }
                        items[i].children.push(...output.items);
                        items[i].children.push(output.result.show10More);
                    } else {
                        if ((arr.length>0) && arr[arr.length - 1].id == "show_more") {
                            items[i].children.pop();
                        }
                        items[i].children.push(...output.items);
                    }
                    return;
                }
                return setChildren(items[i].children, path, ++index, output);
            }
        }
    }


}
